import * as T from './vendor/three.module.js';
export class SparksParticleEmitter{
 constructor(scene,capacity=192){this.capacity=capacity;this.cursor=0;this.position=new Float32Array(capacity*3);this.velocity=new Float32Array(capacity*3);this.life=new Float32Array(capacity);this.color=new Float32Array(capacity*3);this.geometry=new T.BufferGeometry();this.geometry.setAttribute('position',new T.BufferAttribute(this.position,3).setUsage(T.DynamicDrawUsage));this.geometry.setAttribute('color',new T.BufferAttribute(this.color,3).setUsage(T.DynamicDrawUsage));this.material=new T.PointsMaterial({size:.11,vertexColors:true,transparent:true,blending:T.AdditiveBlending,depthWrite:false,toneMapped:false});this.points=new T.Points(this.geometry,this.material);this.points.frustumCulled=false;scene.add(this.points);}
 emit(x,z,speed){const count=Math.min(30,6+Math.floor(speed));for(let j=0;j<count;j++){const i=this.cursor++%this.capacity,k=i*3,a=i*2.399963+this.cursor*.37;this.life[i]=.22+(i%9)*.035;this.position[k]=x;this.position[k+1]=.5;this.position[k+2]=z;this.velocity[k]=Math.sin(a)*(2+speed*.25);this.velocity[k+1]=1.5+(i%7)*.35;this.velocity[k+2]=Math.cos(a)*(2+speed*.25);}}
 update(dt){for(let i=0;i<this.capacity;i++){const k=i*3;if(this.life[i]>0){this.life[i]=Math.max(0,this.life[i]-dt);this.velocity[k+1]-=18*dt;this.position[k]+=this.velocity[k]*dt;this.position[k+1]+=this.velocity[k+1]*dt;this.position[k+2]+=this.velocity[k+2]*dt;}const f=Math.min(1,this.life[i]*5);this.color[k]=f;this.color[k+1]=f*.58;this.color[k+2]=f*.12;}this.geometry.attributes.position.needsUpdate=true;this.geometry.attributes.color.needsUpdate=true;}
 dispose(){this.points.removeFromParent();this.geometry.dispose();this.material.dispose();}
}
